# =============================================================================
# Template for a chapter figure script
#
# 1. Copy this file to r_code/figures/chapter_NN.R.
# 2. Replace every NN, the dataset, and the example figure.
# 3. Run from the project root: Rscript r_code/figures/chapter_NN.R
# 4. Run the checks: Rscript r_code/figures/check_chapter.R NN
# 5. Insert the figures: Rscript r_code/figures/sync_chapter.R NN
#
# The caption and alt text live here, next to the plot code. figures.yml is
# generated by save_book_fig(); do not edit it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(readr)
})

# ---- Data -------------------------------------------------------------------

d <- read_csv("data/REPLACE_ME.csv", show_col_types = FALSE)

# ---- Figure NN.1 ------------------------------------------------------------

p1 <- ggplot(d, aes(x = REPLACE_X, y = REPLACE_Y)) +
  geom_col(
    fill = book_palette[["blue"]], colour = BOOK_INK, linewidth = 0.35
  ) +
  labs(x = "Replace x label", y = "Replace y label") +
  book_theme()

save_book_fig(
  p1,
  chapter = NN,
  id = "NN.1",
  type = "bar",
  slug = "replace_slug",
  caption = "Replace with a caption without the Figure number.",
  alt = paste(
    "Replace with a one-sentence description of the chart type, the",
    "variables, the pattern, and the takeaway."
  ),
  direct_labels = TRUE
)
